/// One declared schema field (spec §1.2, POD): the input shape of
/// [`corvid_set_schema`] and the output shape of
/// [`corvid_schemaiter_next`]. As an INPUT, `name` is non-NULL borrowed
/// UTF-8; as an OUTPUT it is BORROWED from the cursor — valid only
/// until the next `corvid_schemaiter_next` or
/// `corvid_schemaiter_free` on that handle.
final class corvid_field_def extends ffi.Struct {
  /// The field's name.
  external ffi.Pointer<ffi.Char> name;

  /// Name bytes.
  @ffi.Size()
  external int name_len;

  /// The accepted value type (§1.4).
  @ffi.UnsignedInt()
  external int type;

  /// 0 or 1: the field must be present and non-null on every write.
  @ffi.Int()
  external int required;

  /// 0 or 1: no two documents may share this field's value.
  @ffi.Int()
  external int unique;

  static ffi.Pointer<corvid_field_def> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> name,
    required int name_len,
    required int type,
    required int required,
    required int unique,
  }) => $allocator<corvid_field_def>()
    ..ref.name = name
    ..ref.name_len = name_len
    ..ref.type = type
    ..ref.required = required
    ..ref.unique = unique;
}

/// The declared type of a schema field (FFI.md §1.4, frozen per §8):
/// mirrors `corvid::schema::FieldType` (schema.rs `to_byte`, 0..8).
sealed class corvid_field_type {
  /// `FieldType::Any` — any value accepted.
  static const CORVID_FIELD_ANY = 0;

  /// `FieldType::Bool`.
  static const CORVID_FIELD_BOOL = 1;

  /// `FieldType::Int`.
  static const CORVID_FIELD_INT = 2;

  /// `FieldType::Float`.
  static const CORVID_FIELD_FLOAT = 3;

  /// `FieldType::Text`.
  static const CORVID_FIELD_TEXT = 4;

  /// `FieldType::Bytes`.
  static const CORVID_FIELD_BYTES = 5;

  /// `FieldType::Vector`.
  static const CORVID_FIELD_VECTOR = 6;

  /// `FieldType::Array`.
  static const CORVID_FIELD_ARRAY = 7;

  /// `FieldType::Map`.
  static const CORVID_FIELD_MAP = 8;
}

/// One geospatial / weighted hit (spec §1.2, POD): the output shape of
